const proto=figma.root.children.find(p=>p.name==='30 · PROTOTYP · Gesamte App');await figma.setCurrentPageAsync(proto);const roots=proto.children.filter(n=>n.type==='FRAME'),mapping={};for(const f of roots)if(/^[A-Z]\d\d ·/.test(f.name))mapping[f.name.slice(0,3)+(f.width===390?'m':'d')]=f;
const rowLinks={H01:{'Plan prüfen':'P04','Buchungen prüfen':'K07','Kontostände prüfen':'K09'},K01:{Musterkonto:'K02',Bargeld:'K03',Rücklagen:'F07',Musterdepot:'K04'},K10:{'Musterkontakt A':'K11','Musterkontakt B':'K11'},P08:{Musterservice:'P09'},V02:{Musterfonds:'V03'},R17:{'Oktober 2026':'G03','September 2026':'G03'}};
for(const f of Object.values(mapping)){const id=f.name.slice(0,3),mobile=f.width===390;for(const [label,target] of Object.entries(rowLinks[id]||{})){const t=f.findOne(n=>n.type==='TEXT'&&n.characters===label&&n.y>0&&!n.parent.name.startsWith('Navigation'));if(t){const p=t.parent,hit=box(p,'GO '+target+' · Zeile '+label,Math.max(0,t.x-8),t.y-4,Math.min(p.width-t.x+8,mobile?350:700),44,null);}}
 if(id==='G03'){const n=f.findOne(n=>n.name==='Feld / Gehalts-Erwartung');if(n)n.name='GO G05 · Vorhandene Auszahlung wählen';}
 if(id==='G02')await f.setReactionsAsync([{trigger:{type:'AFTER_TIMEOUT',timeout:1.5},actions:[{type:'NODE',destinationId:mapping['G03'+(mobile?'m':'d')].id,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false}]}]);}
let links=0,self=0;const missing=[];for(const f of roots){const suffix=f.width===390?'m':'d';for(const n of f.findAll(n=>/^GO [A-Z]\d\d/.test(n.name))){const target=n.name.slice(3,6),dest=mapping[target+suffix];if(!dest){missing.push([f.name.slice(0,3),n.name]);continue;}if(dest.id===f.id){self++;continue;}await n.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false}]}]);links++;}}
const startD=roots.find(n=>n.name==='START · Desktop'),startM=roots.find(n=>n.name==='START · Phone');figma.currentPage.selection=[startD];figma.viewport.scrollAndZoomIntoView([startD]);return {linked:links,missing,selfTargetsOmitted:self,starts:[startD.id,startM.id],screens:Object.keys(mapping).length};
